import java.util.*;

class Solution {
  public int numDistinctIslands(int[][] grid) {
    Set<String> shapes = new HashSet<>();
    for (int i = 0; i < grid.length; i++)
      for (int j = 0; j < grid[0].length; j++)
        if (grid[i][j] == 1) {
          StringBuilder sb = new StringBuilder();
          walk(grid, i, j, 'o', sb);
          shapes.add(sb.toString());
        }
    return shapes.size();
  }

  // the move sequence, with a marker on every backtrack, identifies the shape
  private void walk(int[][] g, int i, int j, char dir, StringBuilder sb) {
    if (i < 0 || j < 0 || i >= g.length || j >= g[0].length || g[i][j] != 1) return;
    g[i][j] = 0;
    sb.append(dir);
    walk(g, i + 1, j, 'd', sb);
    walk(g, i - 1, j, 'u', sb);
    walk(g, i, j + 1, 'r', sb);
    walk(g, i, j - 1, 'l', sb);
    sb.append('b');
  }
}
